#include <list>

class ScoringManager
{
public:
    class Trick
    {
    public:
        int type;
        int index;
        int flags;
        float time;
        int numSpins;
        float mouthDist;
        float lipDist;
        int repetitions;

        Trick();
        ~Trick() { }
    };

    typedef list<Trick> TrickList;

    class Series
    {
        void *levelTricks;

    public:
        TrickList tricks;
        int numSpins;
        int landing;
        int flags;

        Series();
        ~Series() { }
    };

    typedef list<Series> SeriesList;
    static void stl_prealloc(void);
};

#define MAX_SERIES_PER_CHAIN 32
#define MAX_TRICKS_PER_SERIES 64

void ScoringManager::stl_prealloc(void)
{
    SeriesList slist;
    Series series;
    for (int i = 0; i < MAX_SERIES_PER_CHAIN; i++)
    {
        slist.push_back(series);
    }
    slist.resize(0);
    TrickList tlist;
    Trick trick;
    for (int i = 0; i < MAX_TRICKS_PER_SERIES; i++)
    {
        tlist.push_back(trick);
    }
    tlist.resize(0);
}
